#nullable enable // autogenerated

using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using PVZEngine.Tools.Timing;

namespace MVZ2.GameContent.Effects
{
    [AutoEntityBehaviourDefinition(VanillaEffectNames.nightmarePortalPandora)]
    public class NightmarePortalPandora : EffectBehaviour
    {
        public NightmarePortalPandora(string nsp, string name) : base(nsp, name)
        {

        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            if (!IsClosing(entity))
            {
                entity.Timeout = OPEN_TIMEOUT;
                var spawnTimer = GetOrCreateSpawnTimer(entity);
                if (spawnTimer.RunToExpired())
                {
                    spawnTimer.Reset();
                    var enemyID = GetEnemyID(entity);
                    if (NamespaceID.IsValid(enemyID))
                    {
                        entity.SpawnWithParams(enemyID, entity.Position);
                        entity.PlaySound(VanillaSoundID.odd);
                    }
                }
            }

            entity.SetAnimationBool("Close", entity.Timeout <= CLOSE_TIMEOUT);
        }
        public static void Close(Entity portal)
        {
            SetClosing(portal, true);
            portal.Timeout = CLOSE_TIMEOUT;
        }
        public static bool IsClosing(Entity entity) => entity.GetBehaviourField<bool>(PROP_CLOSING);
        public static void SetClosing(Entity entity, bool value) => entity.SetBehaviourField(PROP_CLOSING, value);
        public static FrameTimer GetOrCreateSpawnTimer(Entity entity) => entity.GetOrCreateTimerSeconds(PROP_SPAWN_TIMER, SPAWN_INTERVAL_SECONDS);
        public static FrameTimer? GetSpawnTimer(Entity entity) => entity.GetBehaviourField<FrameTimer>(PROP_SPAWN_TIMER);
        public static void SetSpawnTimer(Entity entity, FrameTimer? value) => entity.SetBehaviourField(PROP_SPAWN_TIMER, value);
        public static NamespaceID? GetEnemyID(Entity entity) => entity.GetBehaviourField<NamespaceID>(PROP_ENEMY_ID);
        public static void SetEnemyID(Entity entity, NamespaceID value) => entity.SetBehaviourField(PROP_ENEMY_ID, value);

        public const int OPEN_TIMEOUT = 30;
        public const int CLOSE_TIMEOUT = 8;
        public const float SPAWN_INTERVAL_SECONDS = 12f;
        public static readonly VanillaEntityPropertyMeta<bool> PROP_CLOSING = new VanillaEntityPropertyMeta<bool>("closing");
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_SPAWN_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("spawn_timer");
        public static readonly VanillaEntityPropertyMeta<NamespaceID> PROP_ENEMY_ID = new VanillaEntityPropertyMeta<NamespaceID>("enemy_id");
    }
}